   127→		null,
   128→	);
   129→	const [activeTab, setActiveTab] = useState<"build" | "preview">("build");
   130→	const [questions, setQuestions] = useState(initialQuestions);
   131→	const [activeDragItem, setActiveDragItem] = useState<DragItem | null>(null);
   132→	const [overId, setOverId] = useState<string | null>(null);
   133→	const [paletteOpen, setPaletteOpen] = useState(false);
   134→	const [propertiesOpen, setPropertiesOpen] = useState(false);
   135→
