   218→		const { over } = event;
   219→		setOverId(over?.id as string | null);
   220→	};
   221→
   222→	const handleDragEnd = (event: DragEndEvent) => {
   223→		const { active, over } = event;
   224→		setActiveDragItem(null);
   225→		setOverId(null);
   226→
   227→		if (!over) return;
   228→
   229→		// Handle palette drop on canvas (create new question at end)
   230→		if (active.data.current?.questionType && over.id === "canvas") {
   231→			const questionType = active.data.current.questionType as Question["type"];
   232→			createMutation.mutate({
   233→				surveyId: survey.id,
   234→				type: questionType,
   235→				title: `New ${questionTypeLabels[questionType] || questionType}`,
   236→				order: questions.length,
   237→			});
   238→			return;
   239→		}
   240→
   241→		// Handle palette drop on a specific question (insert before it)
   242→		if (active.data.current?.questionType && over.id !== "canvas") {
   243→			const questionType = active.data.current.questionType as Question["type"];
   244→			const targetIndex = questions.findIndex((q) => q.id === over.id);
   245→
   246→			if (targetIndex !== -1) {
   247→				// Use client directly to handle insertion at specific position
   248→				client.question
   249→					.create({
   250→						surveyId: survey.id,
   251→						type: questionType,
   252→						title: `New ${questionTypeLabels[questionType] || questionType}`,
   253→						order: targetIndex,
   254→					})
   255→					.then((newQuestion) => {
   256→						// Build the new array with correct order
   257→						const reorderedQuestions = [
   258→							...questions
   259→								.slice(0, targetIndex)
   260→								.map((q, i) => ({ ...q, order: i })),
   261→							{ ...newQuestion, order: targetIndex },
   262→							...questions
   263→								.slice(targetIndex)
   264→								.map((q, i) => ({ ...q, order: targetIndex + 1 + i })),
   265→						];
   266→
   267→						setQuestions(reorderedQuestions);
   268→						setSelectedQuestionId(newQuestion.id);
   269→						queryClient.invalidateQueries({ queryKey: ["question"] });
   270→
   271→						// Reorder all questions on backend
   272→						reorderMutation.mutate({
   273→							questions: reorderedQuestions.map((q) => ({
   274→								id: q.id,
   275→								order: q.order,
   276→							})),
   277→						});
   278→
   279→						toast.success("Question added");
   280→					})
   281→					.catch((error: Error) => {
   282→						toast.error(error.message || "Failed to create question");
   283→					});
   284→			}
   285→			return;
   286→		}
   287→
   288→		// Handle reordering
   289→		if (active.id !== over.id && over.id !== "canvas") {
   290→			const oldIndex = questions.findIndex((q) => q.id === active.id);
   291→			const newIndex = questions.findIndex((q) => q.id === over.id);
   292→
   293→			if (oldIndex !== -1 && newIndex !== -1) {
   294→				const newQuestions = arrayMove(questions, oldIndex, newIndex).map(
   295→					(q, index) => ({
   296→						...q,
   297→						order: index,
   298→					}),
   299→				);
   300→
   301→				setQuestions(newQuestions);
   302→
   303→				reorderMutation.mutate({
   304→					questions: newQuestions.map((q) => ({
   305→						id: q.id,
   306→						order: q.order,
   307→					})),
   308→				});
   309→			}
   310→		}
   311→	};
   312→
   313→	const contextValue: SurveyBuilderContextValue = {
   314→		survey,
   315→		questions,
   316→		selectedQuestionId,
   317→		setSelectedQuestionId,
   318→		activeTab,
   319→		setActiveTab,
   320→		onQuestionsChange: setQuestions,
   321→		paletteOpen,
   322→		setPaletteOpen,
   323→		propertiesOpen,
   324→		setPropertiesOpen,
   325→	};
   326→
   327→	const safeQuestions = questions || [];
   328→
   329→	// Custom drop animation that fades out smoothly
   330→	const dropAnimation: typeof defaultDropAnimation = {
   331→		...defaultDropAnimation,
   332→		duration: 200,
   333→		keyframes: ({ transform }) => [
   334→			{ opacity: 1, transform: CSS.Transform.toString(transform.initial) },
   335→			{
   336→				opacity: 0,
   337→				transform: CSS.Transform.toString({
   338→					...transform.final,
   339→					scale: 0.9,
   340→				} as any),
   341→			},
   342→		],
   343→	};
   344→
   345→	// Render drag overlay
   346→	const renderDragOverlay = () => {
   347→		if (!activeDragItem) return null;
   348→
   349→		if (activeDragItem.type === "palette") {
   350→			const Icon =
   351→				questionTypeIcons[activeDragItem.questionType] || ClipboardList;
   352→			return (
   353→				<Card className="border-2 border-violet-300 bg-white/95 shadow-xl backdrop-blur-sm">
   354→					<CardContent className="flex items-center gap-3 p-4">
   355→						<div className="rounded bg-violet-100 p-1.5">
   356→							<Icon className="h-4 w-4 text-violet-600" />
   357→						</div>
   358→						<span className="font-medium">
   359→							{questionTypeLabels[activeDragItem.questionType] ||
   360→								activeDragItem.questionType}
   361→						</span>
   362→					</CardContent>
   363→				</Card>
   364→			);
   365→		}
   366→
   367→		// Dragging existing question
   368→		const activeQuestion = safeQuestions.find(
   369→			(q) => q.id === activeDragItem.id,
