// Drag item types
interface PaletteDragItem {
	type: "palette";
	questionType: Question["type"];
}

interface QuestionDragItem {
	type: "question";
	id: string;
}

type DragItem = PaletteDragItem | QuestionDragItem;

interface SurveyBuilderProps {
	survey: Survey;
	questions: Question[];
	className?: string;
}

export function SurveyBuilder({
	survey,
	questions: initialQuestions,
	className,
}: SurveyBuilderProps) {
	const [selectedQuestionId, setSelectedQuestionId] = useState<string | null>(
		null,
	);
	const [activeTab, setActiveTab] = useState<"build" | "preview">("build");
	const [questions, setQuestions] = useState(initialQuestions);
	const [activeDragItem, setActiveDragItem] = useState<DragItem | null>(null);
	const [overId, setOverId] = useState<string | null>(null);
	const [paletteOpen, setPaletteOpen] = useState(false);
	const [propertiesOpen, setPropertiesOpen] = useState(false);

	// Responsive breakpoints
	const isDesktop = useMediaQuery("(min-width: 1024px)");

	const queryClient = useQueryClient();

	// Sync state when initialQuestions changes
	useEffect(() => {
		setQuestions(initialQuestions);
	}, [initialQuestions]);

	// Create question mutation (for palette drops)
	const createMutation = useMutation(
		orpc.question.create.mutationOptions({
			onSuccess: (newQuestion) => {
				setQuestions((prev) => [...prev, newQuestion]);
				setSelectedQuestionId(newQuestion.id);
				queryClient.invalidateQueries({ queryKey: ["question"] });
				toast.success("Question added");
			},
			onError: (error) => {
				toast.error(error.message || "Failed to create question");
			},
		}),
	);

	// Reorder mutation
	const reorderMutation = useMutation(
		orpc.question.reorder.mutationOptions({
			onSuccess: () => {
				queryClient.invalidateQueries({ queryKey: ["question"] });
			},
			onError: (error) => {
				toast.error(error.message || "Failed to reorder questions");
			},
		}),
	);

	// DnD sensors
	const sensors = useSensors(
		useSensor(PointerSensor, {
			activationConstraint: {
				distance: 5,
			},
		}),
		useSensor(KeyboardSensor, {
			coordinateGetter: sortableKeyboardCoordinates,
		}),
	);

	// Custom collision detection: pointerWithin for palette drops, closestCenter for canvas reordering
	const collisionDetection: CollisionDetection = (args) => {
		// If dragging from palette (has questionType), use pointerWithin for cross-container drops
		if (args.active.data.current?.questionType) {
			const pointerCollisions = pointerWithin(args);
			if (pointerCollisions.length > 0) {
				return pointerCollisions;
			}
		}
		// For canvas reordering, use closestCenter for better sortable behavior
		return closestCenter(args);
	};

	const handleDragStart = (event: DragStartEvent) => {
		const { active } = event;
		const data = active.data.current;

		if (data?.questionType) {
			// Dragging from palette
			setActiveDragItem({
				type: "palette",
				questionType: data.questionType as Question["type"],
			});
		} else {
			// Dragging existing question
			setActiveDragItem({
				type: "question",
				id: active.id as string,
			});
		}
	};

	const handleDragOver = (event: DragOverEvent) => {
		const { over } = event;
		setOverId(over?.id as string | null);
	};

	const handleDragEnd = (event: DragEndEvent) => {
		const { active, over } = event;
		setActiveDragItem(null);
		setOverId(null);

		if (!over) return;

		// Handle palette drop on canvas (create new question at end)
		if (active.data.current?.questionType && over.id === "canvas") {
			const questionType = active.data.current.questionType as Question["type"];
			createMutation.mutate({
				surveyId: survey.id,
				type: questionType,
				title: `New ${questionTypeLabels[questionType] || questionType}`,
				order: questions.length,
			});
			return;
		}

		// Handle palette drop on a specific question (insert before it)
		if (active.data.current?.questionType && over.id !== "canvas") {
			const questionType = active.data.current.questionType as Question["type"];
			const targetIndex = questions.findIndex((q) => q.id === over.id);

			if (targetIndex !== -1) {
				// Use client directly to handle insertion at specific position
				client.question
					.create({
						surveyId: survey.id,
						type: questionType,
						title: `New ${questionTypeLabels[questionType] || questionType}`,
						order: targetIndex,
					})
					.then((newQuestion) => {
						// Build the new array with correct order
						const reorderedQuestions = [
							...questions
								.slice(0, targetIndex)
								.map((q, i) => ({ ...q, order: i })),
							{ ...newQuestion, order: targetIndex },
							...questions
								.slice(targetIndex)
								.map((q, i) => ({ ...q, order: targetIndex + 1 + i })),
						];

						setQuestions(reorderedQuestions);
						setSelectedQuestionId(newQuestion.id);
						queryClient.invalidateQueries({ queryKey: ["question"] });

						// Reorder all questions on backend
						reorderMutation.mutate({
							questions: reorderedQuestions.map((q) => ({
								id: q.id,
								order: q.order,
							})),
						});

						toast.success("Question added");
					})
					.catch((error: Error) => {
						toast.error(error.message || "Failed to create question");
					});
			}
			return;
		}

		// Handle reordering
		if (active.id !== over.id && over.id !== "canvas") {
			const oldIndex = questions.findIndex((q) => q.id === active.id);
			const newIndex = questions.findIndex((q) => q.id === over.id);

			if (oldIndex !== -1 && newIndex !== -1) {
				const newQuestions = arrayMove(questions, oldIndex, newIndex).map(
					(q, index) => ({
						...q,
						order: index,
					}),
				);

				setQuestions(newQuestions);

				reorderMutation.mutate({
					questions: newQuestions.map((q) => ({
						id: q.id,
						order: q.order,
					})),
				});
			}
		}
	};

	const contextValue: SurveyBuilderContextValue = {
		survey,
		questions,
		selectedQuestionId,
		setSelectedQuestionId,
		activeTab,
		setActiveTab,
		onQuestionsChange: setQuestions,
		paletteOpen,
		setPaletteOpen,
		propertiesOpen,
		setPropertiesOpen,
	};

